<?php
$type=in_array(getstr('type'),['pages','sectors','projects'])?getstr('type'):'pages';$id=(int)getstr('id');$locale=in_array(getstr('locale'),['ar','en'])?getstr('locale'):'ar';
$entity=$id?query("SELECT * FROM $type WHERE id=?",[$id])->fetch():['id'=>0,'slug'=>'','status'=>'draft','sort_order'=>0,'image_id'=>null,'sector_id'=>null,'gallery'=>'[]'];
if(!$entity){echo '<div class="notice error">المحتوى غير موجود.</div>';return;}
$translation=$id?query('SELECT * FROM translations WHERE entity_type=? AND entity_id=? AND locale=?',[$type,$id,$locale])->fetch():false;
$tr=$translation?:['title'=>'','summary'=>'','body'=>'{"sections":[]}','seo_title'=>'','seo_description'=>'','status'=>'draft','approval'=>'review','source_ref'=>''];$body=json_decode($tr['body'],true);
if(!$translation&&$id){$base=query('SELECT body FROM translations WHERE entity_type=? AND entity_id=? LIMIT 1',[$type,$id])->fetchColumn();if($base){$body=json_decode($base,true);foreach($body['sections']??[] as &$section){$section['title']='';$section['text']='';$section['items']=[];}unset($section);$body['slider']=[];$body['eyebrow']='';$body['services']=[];$body['text']='';}}
require_once ROOT.'/app/admin-form-helpers.php';
$mediaOptions=[''=>'بدون صورة'];foreach(query("SELECT id,original_name FROM media WHERE mime LIKE 'image/%' ORDER BY id DESC") as $m)$mediaOptions[$m['id']]='#'.$m['id'].' — '.$m['original_name'];
